"use strict";(self.webpackChunkuniplus_developers=self.webpackChunkuniplus_developers||[]).push([["84337"],{99279(o){o.exports=JSON.parse('{"registro":{"codigo":"uniplus.estrutura_formulario.etapa_codigo_duplicado","status":422,"titulo":"O c\xf3digo de etapa se repete no formul\xe1rio"},"descricao":{"codigo":"uniplus.estrutura_formulario.etapa_codigo_duplicado","requisitos":[],"oQueAconteceu":["Duas etapas do formul\xe1rio t\xeam o mesmo `codigo`. O c\xf3digo \xe9 o que os itens e os grupos usam em `etapaCodigo` para dizer em que se\xe7\xe3o est\xe3o, e por isso \xe9 \xfanico no formul\xe1rio. A compara\xe7\xe3o \xe9 exata e diferencia mai\xfasculas de min\xfasculas. A mensagem \xe9 \\"O c\xf3digo de etapa \'`{c\xf3digo\\\\}`\' se repete no formul\xe1rio.\\"","A recusa vem na lista `errors` da resposta, com `field` igual a `etapas[i].codigo`; nos modelos de formul\xe1rio o `field` come\xe7a por `conteudo.`. Nada \xe9 gravado. A entrada aponta a segunda ocorr\xeancia e as seguintes; a primeira fica de fora da recusa.","A estrutura das etapas s\xf3 \xe9 conferida quando todas as etapas t\xeam forma v\xe1lida, e as recusas da estrutura saem juntas, na mesma lista. Na grava\xe7\xe3o do formul\xe1rio do processo, a forma de cada etapa \xe9 conferida primeiro e, havendo recusa, a estrutura s\xf3 \xe9 conferida se todas as etapas foram formadas. No modelo, a estrutura s\xf3 \xe9 conferida quando o conte\xfado n\xe3o tem nenhuma outra recusa de forma, e os itens s\xe3o conferidos contra as etapas s\xf3 depois que a estrutura das etapas passa.","Nos modelos de formul\xe1rio, a confer\xeancia s\xf3 ocorre quando o conte\xfado foi lido sem recusa de leitura (como a de [conte\xfado malformado](/erros/uniplus.configuracao.modelo_formulario.entrada_malformada)), e na atualiza\xe7\xe3o um `{id}` que n\xe3o existe \xe9 recusado antes, como [modelo de formul\xe1rio n\xe3o encontrado](/erros/uniplus.configuracao.modelo_formulario.nao_encontrado)."],"comoResolver":["D\xea a cada etapa um `codigo` distinto e, se h\xe1 itens ou grupos que apontavam para a etapa repetida, confira o `etapaCodigo` deles. Depois disso, grave de novo."],"ondeAparece":["Cria\xe7\xe3o de um modelo de formul\xe1rio","Atualiza\xe7\xe3o de um modelo de formul\xe1rio","Grava\xe7\xe3o do formul\xe1rio do processo"]},"modulo":{"id":"transversais","nome":"Erros transversais","assunto":"Estrutura formulario"},"origem":{"repositorio":"unifesspa-edu-br/uniplus-api","commit":"137e6bdd986deaebbd7281a2e43c40e18a247a98"}}')}}]);